function expandPP(spath,title,year){if(!spath)
return"";if(!isNaN(spath)){return"./posters/"+spath;}
var fpath="";if(spath.indexOf('@')===0){fpath+='commons/thumb/';spath=spath.slice(1);}else{fpath+='en/thumb/';}
fpath+=spath[0]+"/"+spath[1]+spath[2]+"/";spath=spath.slice(3);fpath+=spath.replace("&",title.replaceAll(" ","_"),).replaceAll("=","poster").replaceAll("!","Poster").replaceAll("+","film").replaceAll(",","Film").replace("*",".jpg").replaceAll("<","movie").replaceAll(">","Movie").replace("^",".JPG").replace("?",".jpeg").replaceAll("~",year);return"https://upload.wikimedia.org/wikipedia/"+fpath+"/220px-"+fpath.split("/").slice(-1);}
var tooltip=function(ele){var n;var i;var h=false;if(!(window.innerWidth<1024)){(n=ele.tooltipster({contentAsHTML:true,updateAnimation:false,arrow:false,side:["right","left"],interactive:true,delay:200,minWidth:320,maxWidth:320,content:"Loading..",functionBefore:function(n,t){if(!h){h=true;$.ajax("tooltips/".concat(ele.data("tip")),{dataType:"html"}).done(function(t){return n.content(t);});}},functionPosition:function(t,n,i){if("left"===i.side){i.coord.left+=0.5*n.geo.origin.size.width;}else{i.coord.left-=0.5*n.geo.origin.size.width;}
i.coord.top-=(n.geo.origin.size.height-i.size.height)/2;i.coord.top+=0.5*n.geo.origin.size.height;return i;}}).tooltipster("instance")).on("before",i=function(){setTimeout(function(){try{$(ele.tooltipster("elementTooltip")).activate();}catch(t){}},10);});n.on("updated",i);}}
let movies=[];let allMovies=[];moviedb.forEach(mo=>{mo[4]=mo[4].split("|").map(m=>!isNaN(m)?actorsFreq[m]:m);mo[5]=mo[5].split("|").map(m=>!isNaN(m)?dirFreq[m]:m);mo[2]=mo[2].split("|").map(m=>genres[m]);mo[1]=mo[1]>=24?1900+mo[1]:2000+mo[1];if(mo.length==7)
{mo.push('');}else{mo[7]=expandPP(mo[7],mo[0],mo[1]);}
if(mo.length==8)
{mo.push(0);}
let movie={};props.forEach(p=>{movie[p]=mo[props.indexOf(p)];})
movie.tooltip=movie.original_title.replaceAll(' ','').replace(/[^a-zA-Z 0-9]+/g,'')+movie.year_of_release;movies.push(movie);});allMovies=sort([...movies],"imdb_rating");document.getElementById("searchAll").addEventListener("keydown",function(event){if(event.key==="Enter"&&document.getElementById("searchAll").value){event.preventDefault();searchAll();}});function renderPage(page){document.getElementById("cards").innerHTML='';if(!page||!page.length){document.getElementById("cards").insertAdjacentHTML('beforeend',"<h3>No Results</h3>");}else{page.forEach(d=>document.getElementById("cards").insertAdjacentHTML('beforeend',getNewDivTemplate(d)));document.querySelectorAll('.tooltipstered').forEach(e=>tooltip($(e)));}}
function getNewDivTemplate(mov){var div=`<div class="movie-item item"><div class="item-inner"><a class="cover tooltipstered"data-tip="${mov.tooltip}"onclick="openYT('${mov.yt}','${mov.tplus}','${mov.original_title}');"><div><img class=" ls-is-cached lazyloaded"
src="${mov.poster_path}"alt="${mov.original_title}"></div></a><div class="detail"><div class="title">${mov.original_title}</div><div class="info"><span class="type">${mov.year_of_release}</span><span><i class="fa-solid fa-star"></i>${mov.imdb_rating}</span></div></div></div></div>`;return div;}
function openYT(yt,tplus,title){window.open("https://www.youtube.com/watch?v="+yt+(tplus!=undefined?"&t="+tplus:""),'_blank').focus();}
function createPagination(totPages){totPages=totPages||1;window.pagObj=$('#pagination').twbsPagination({totalPages:totPages,visiblePages:5,first:"<i class=\"fa-solid fa-angles-left\"></i>",prev:"<i class=\"fa-solid fa-angle-left\"></i>",next:"<i class=\"fa-solid fa-angle-right\"></i>",last:"<i class=\"fa-solid fa-angles-right\"></i>",onPageClick:function(event,pageNumber){if(!firstPageLoad){renderPage(pages[pageNumber-1]);}
firstPageLoad=false;}}).on('page',function(event,page){});}
function paginate(arr,size){return arr.reduce((acc,val,i)=>{let idx=Math.floor(i/size)
let page=acc[idx]||(acc[idx]=[])
page.push(val)
return acc},[])}
var change=function(n){var e;var o;var f="";var c=$(this).closest(".dropdown-menu");var W=c.parent().find("[data-label-placement]");if((W=W&&W.length?W:c.parent().find("[data-toggle=\"dropdown\"]"))&&W.length&&false!==W.data("placeholder")&&(null==W.data("placeholder")&&W.data("placeholder",$.trim(W.text())),f=$.data(W[0],"placeholder"),e=parseInt(W.data("maxItems")),isNaN(e)&&(e=1),o=(o=W.data("maxText"))||"%s selected",(c=c.find("li > input:checked")).length&&(f=[],c.each(function(){var t;var r=$(this).parent().find("label").eq(0);var e=r.find(".data-label");if(r=(e.length?((t=$("<p></p>")).append(e.clone()),t):r).html()){f.push($.trim(r));}}),f=f.length>e?o.replace("%s",f.length):f.join(", ")),c=W.find(".caret"),W.html(f||""),c.length)&&W.append(" ")){c.appendTo(W);}};document.querySelectorAll(".dropdown-menu li input").forEach(e=>e.onchange=change);function filterAll(){movies=[...allMovies];var selectedGenre=[...document.querySelectorAll('input[name=genre]:checked')].map(f=>f.value);if(selectedGenre.length){movies=movies.filter(movie=>selectedGenre.some(gen=>movie.genres.includes(gen)));}
var selectedYear=[...document.querySelectorAll('input[name=year]:checked')].map(f=>f.value);if(selectedYear.length){movies=movies.filter(movie=>selectedYear.some(years=>{let startYear,endYear;[startYear,endYear]=years.split("-");return movie.year_of_release>=Number(startYear)&&movie.year_of_release<=Number(endYear)}));}else{}
movies=sort(movies,document.querySelector('input[name=sort]:checked')?.value);pages=paginate(movies,pageSize);$('#pagination').twbsPagination('destroy');createPagination(pages.length);}
function searchAll(){var searchText=document.getElementById("searchAll").value;var searchIn=document.getElementById("searchIn").innerHTML;if(searchText.length){movies=[...allMovies];switch(searchIn){case"Title":movies=movies.filter(movie=>~movie.original_title.toUpperCase().indexOf(searchText.toUpperCase()));break;case"Actor":{movies=movies.filter(movie=>movie.actors.filter(actor=>!!actor&&~actor.toUpperCase().indexOf(searchText.toUpperCase())).length>0);break;}
case"Director":{movies=movies.filter(movie=>movie.director.filter(director=>!!director&&~director.toUpperCase().indexOf(searchText.toUpperCase())).length>0);break;}}}else if(movies.length!=allMovies.length){movies=[...allMovies];}
pages=paginate(movies,pageSize);$('#pagination').twbsPagination('destroy');createPagination(pages.length);}
function sort(movs,sortBy){sortBy=sortBy||"year_of_release";if(sortBy=="original_title"){movs.sort((a,b)=>a[sortBy].localeCompare(b[sortBy]));}else{movs.sort((a,b)=>(a[sortBy]-b[sortBy])||(a["year_of_release"]-b["year_of_release"]));}
if(sortBy==="imdb_rating")
movs.sort((a,b)=>(b[sortBy]-a[sortBy])||!(b["year_of_release"]-a["year_of_release"]));return movs;}
var searchInField="Title";function searchIn(item){document.getElementById("searchIn").innerHTML=item.innerHTML;searchInField=item.innerHTML;document.getElementsByName("keyword")[0].placeholder="Search "+item.innerHTML.toLowerCase()+"s";}
window.openYT=openYT;function init(){createPagination(pages.length);document.querySelectorAll('.tooltipstered').forEach(e=>tooltip($(e)));}
let pageSize=32;let pages=paginate(allMovies,pageSize);var firstPageLoad=true;init();$(document)
.on("click.bs.dropdown.data-api",".dropdown-menu li > input[type=\"checkbox\"] ~ label, .dropdown-menu li > input[type=\"checkbox\"], .dropdown-menu.noclose li, .dropdown-menu.noclose",function(n){n.stopPropagation();})
